    rdfs:comment "Relates an invoice line to its item detail (reification)." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :InvoiceLineItemDetail .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Relates an invoice line item detail to the item." ;
    rdfs:domain :InvoiceLineItemDetail ;
    rdfs:range :Item .

:hasPrice a owl:ObjectProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Relates an invoice line item detail to the price." ;
    rdfs:domain :InvoiceLineItemDetail ;
    rdfs:range :Price .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Relates an invoice summary section to the tax." ;
    rdfs:domain :InvoiceSummarySection ;
    rdfs:range :Tax .

